CREATE TABLE IF NOT EXISTS ft_site (
  id VARCHAR(64) PRIMARY KEY,
  code VARCHAR(32) NOT NULL,
  name VARCHAR(256) NOT NULL,
  site_type VARCHAR(32) NOT NULL,
  sections_count INTEGER NOT NULL DEFAULT 0,
  livestock INTEGER NOT NULL DEFAULT 0,
  status VARCHAR(16) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_section (
  id VARCHAR(64) PRIMARY KEY,
  site_id VARCHAR(64) NOT NULL,
  name VARCHAR(256) NOT NULL,
  pigs INTEGER NOT NULL DEFAULT 0,
  temp DOUBLE PRECISION NOT NULL DEFAULT 0,
  humidity DOUBLE PRECISION NOT NULL DEFAULT 0,
  ventilation DOUBLE PRECISION NOT NULL DEFAULT 0,
  feed_ok BOOLEAN NOT NULL DEFAULT TRUE,
  water_ok BOOLEAN NOT NULL DEFAULT TRUE,
  state VARCHAR(16) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_alarm (
  id VARCHAR(64) PRIMARY KEY,
  at_ts TIMESTAMPTZ NOT NULL,
  site_id VARCHAR(64) NOT NULL,
  source VARCHAR(256) NOT NULL,
  message VARCHAR(1024) NOT NULL,
  severity VARCHAR(16) NOT NULL,
  status VARCHAR(16) NOT NULL,
  tag VARCHAR(128)
);
CREATE TABLE IF NOT EXISTS ft_task (
  id VARCHAR(64) PRIMARY KEY,
  title VARCHAR(512) NOT NULL,
  source VARCHAR(256),
  site_id VARCHAR(64) NOT NULL,
  assignee VARCHAR(128),
  status VARCHAR(32) NOT NULL,
  priority VARCHAR(16) NOT NULL DEFAULT 'normal',
  due_at TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS ft_decision (
  id VARCHAR(64) PRIMARY KEY,
  severity VARCHAR(16) NOT NULL,
  title VARCHAR(512) NOT NULL,
  recommendation VARCHAR(2048) NOT NULL,
  site_id VARCHAR(64) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'active',
  reject_comment VARCHAR(1024)
);
CREATE TABLE IF NOT EXISTS ft_decision_action (
  decision_id VARCHAR(64) NOT NULL,
  ord INTEGER NOT NULL,
  text VARCHAR(512) NOT NULL,
  PRIMARY KEY (decision_id, ord)
);
CREATE TABLE IF NOT EXISTS ft_integration (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(256) NOT NULL,
  protocol VARCHAR(64) NOT NULL,
  status VARCHAR(16) NOT NULL,
  lag_sec INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS ft_trend_param (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(256) NOT NULL,
  unit VARCHAR(32) NOT NULL,
  color VARCHAR(32) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_trend_point (
  param_id VARCHAR(64) NOT NULL,
  t_label VARCHAR(16) NOT NULL,
  sort_order INTEGER NOT NULL,
  value DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (param_id, sort_order)
);
CREATE TABLE IF NOT EXISTS ft_health_case (
  id VARCHAR(64) PRIMARY KEY,
  pen VARCHAR(128) NOT NULL,
  activity INTEGER NOT NULL,
  norm INTEGER NOT NULL,
  risk VARCHAR(16) NOT NULL,
  note VARCHAR(1024),
  temp DOUBLE PRECISION,
  group_size INTEGER,
  actions_json TEXT
);
ALTER TABLE ft_health_case ADD COLUMN IF NOT EXISTS actions_json TEXT;
CREATE TABLE IF NOT EXISTS ft_camera (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(128) NOT NULL,
  place VARCHAR(256) NOT NULL,
  status VARCHAR(16) NOT NULL,
  kind VARCHAR(64),
  fps INTEGER,
  bitrate VARCHAR(32),
  latency_ms INTEGER,
  storage VARCHAR(64)
);
CREATE TABLE IF NOT EXISTS ft_video_event (
  id VARCHAR(64) PRIMARY KEY,
  at_ts TIMESTAMPTZ NOT NULL,
  place VARCHAR(256) NOT NULL,
  factor VARCHAR(128) NOT NULL,
  animal_count INTEGER DEFAULT 0,
  severity VARCHAR(16) NOT NULL,
  detail VARCHAR(1024),
  cam_id VARCHAR(64)
);
CREATE TABLE IF NOT EXISTS ft_detector (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(256) NOT NULL,
  load_pct INTEGER NOT NULL DEFAULT 0,
  state VARCHAR(32) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_robot (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(128) NOT NULL,
  site_code VARCHAR(32) NOT NULL,
  state VARCHAR(16) NOT NULL,
  battery INTEGER NOT NULL DEFAULT 0,
  mode VARCHAR(64),
  last_job VARCHAR(256)
);
CREATE TABLE IF NOT EXISTS ft_robot_mission (
  id VARCHAR(64) PRIMARY KEY,
  robot_id VARCHAR(64),
  at_label VARCHAR(32) NOT NULL,
  text VARCHAR(512) NOT NULL,
  zone VARCHAR(128),
  route VARCHAR(256)
);
CREATE TABLE IF NOT EXISTS ft_animal (
  id VARCHAR(64) PRIMARY KEY,
  rfid VARCHAR(64) NOT NULL,
  pen VARCHAR(128) NOT NULL,
  board VARCHAR(64),
  status VARCHAR(32) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_scan (
  id VARCHAR(64) PRIMARY KEY,
  at_label VARCHAR(32) NOT NULL,
  rfid VARCHAR(64) NOT NULL,
  place VARCHAR(256) NOT NULL,
  result VARCHAR(128) NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_kpi (
  key VARCHAR(64) PRIMARY KEY,
  value DOUBLE PRECISION NOT NULL
);
CREATE TABLE IF NOT EXISTS ft_user (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(128) NOT NULL,
  email VARCHAR(256) NOT NULL,
  role VARCHAR(32) NOT NULL,
  site_id VARCHAR(64)
);
CREATE TABLE IF NOT EXISTS ft_sppr_config (
  site_id VARCHAR(64) PRIMARY KEY,
  activity_norm INTEGER NOT NULL DEFAULT 75,
  temp_risk DOUBLE PRECISION NOT NULL DEFAULT 26.0
);
